// Changes: Tests of the precedence-table module through its interface (terminals, relations, grid, checks, simulation).

import { describe, expect, it } from 'vitest'
import { defaultProjectData } from './project'
import { analyzePrec, cycleRelation, precTable, precTableSize, relation, setRelation, setTerminals } from './precedence'

const empty = () => defaultProjectData().prec

describe('setTerminals', () => {
  it('keeps each terminal once, in order, and never $ – the table adds $ itself', () => {
    const p = setTerminals(empty(), ['+', 'i', '$', '+', '', '*'])
    expect(p.terminals).toEqual(['+', 'i', '*'])
  })
})

describe('relations', () => {
  it('reads back what was set; an empty relation clears the cell', () => {
    let p = setTerminals(empty(), ['+', 'i'])
    p = setRelation(p, '+', 'i', '<')
    p = setRelation(p, 'i', '$', '>')
    expect(relation(p, '+', 'i')).toBe('<')
    expect(relation(p, 'i', '$')).toBe('>')
    expect(relation(p, 'i', '+')).toBe('')
    p = setRelation(p, '+', 'i', '')
    expect(relation(p, '+', 'i')).toBe('')
  })

  it('cycles empty → < → = → > → empty', () => {
    let p = setTerminals(empty(), ['i'])
    const seen = []
    for (let n = 0; n < 4; n++) {
      p = cycleRelation(p, 'i', '$')
      seen.push(relation(p, 'i', '$'))
    }
    expect(seen).toEqual(['<', '=', '>', ''])
  })

  it('forgets the relations of a removed terminal and keeps the others', () => {
    let p = setTerminals(empty(), ['+', 'i'])
    p = setRelation(p, '+', 'i', '<')
    p = setRelation(p, 'i', '+', '>')
    p = setRelation(p, '$', 'i', '<')
    p = setTerminals(p, ['i'])
    expect(relation(p, '$', 'i')).toBe('<')
    p = setTerminals(p, ['i', '+'])
    expect(relation(p, '+', 'i')).toBe('')
    expect(relation(p, 'i', '+')).toBe('')
  })
})

describe('precTable', () => {
  it('is empty until terminals are set', () => {
    expect(precTable(empty()).columns).toEqual([])
  })

  it('has the terminals as rows and columns with $ last', () => {
    let p = setTerminals(empty(), ['+', 'i'])
    p = setRelation(p, '+', 'i', '<')
    p = setRelation(p, '$', '+', '<')
    const t = precTable(p)
    expect(t.columns).toEqual(['+', 'i', '$'])
    expect(t.rows).toEqual([
      { terminal: '+', relations: ['', '<', ''] },
      { terminal: 'i', relations: ['', '', ''] },
      { terminal: '$', relations: ['<', '', ''] },
    ])
  })
})

describe('precTableSize', () => {
  it('counts $ as a row once there are terminals', () => {
    expect(precTableSize(empty())).toBe(0)
    expect(precTableSize({ terminals: ['+', 'i'] })).toBe(3)
    expect(precTableSize({ terminals: ['+', '$', '+'] })).toBe(2)
  })
})

describe('analyzePrec', () => {
  it('asks for terminals while the table is empty (the generator is gone)', () => {
    const texts = analyzePrec(empty()).problems.map((p) => p.text)
    expect(texts).toContain('Zadaj terminály tabuľky alebo načítaj príklad.')
    expect(texts.join(' ')).not.toMatch(/generátor/)
  })

  it('reports ε-rules, duplicate right sides and rule terminals missing from the table', () => {
    const p = { ...setTerminals(empty(), ['i']), rules: 'E -> i\nF -> i\nG -> ε\nE -> x' }
    const { problems } = analyzePrec(p)
    expect(problems.filter((x) => x.level !== 'info').map((x) => x.text)).toEqual([
      'Pravidlá 1 a 2 majú rovnakú pravú stranu (i)',
      'Pravidlo 3 je ε-pravidlo – precedenčná SA ich nepovoľuje',
      'Terminál x z pravidla 4 nie je v tabuľke',
    ])
  })

  it('stops the simulation at an empty cell', () => {
    const p = { ...setTerminals(empty(), ['i']), rules: 'E -> i', input: 'i' }
    expect(analyzePrec(p).simulation).toMatchObject({ ok: false, message: 'Prázdna bunka [$, i]' })
  })
})
